(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

	// Add your code here
	var year = source.u_baujahr_beginn;
    if (year && year.length === 4 && !isNaN(parseInt(year))) {
		gs.info(year+'-01-01');
		gs.info(typeof(year));
        target.production_year_from= year + '-01-01'; // No time part needed
    }
    gs.info(year+'-01-01'); // leave empty if invalid
	gs.info(typeof(year));
	target.production_year_from= year + '-01-01'; // return the value to be put into the target field

})(source, map, log, target);
